configuration.expression:
irrigationTask.consumption = currentIrrigationWaterConsumption;
irrigationTask.duration = ctx.latestTs - irrigationTask.startTs;

var values = {
    "irrigationTask": irrigationTask
};


var shouldTurnOff = false;

if (irrigationTask == null) {
    shouldTurnOff = true;
} else if (irrigationTask.durationThreshold > 0) {
    shouldTurnOff = (irrigationTask.startTs + irrigationTask.durationThreshold) <= ctx.latestTs;
} else {
    shouldTurnOff = currentIrrigationWaterConsumption >= irrigationTask.consumptionThreshold;
}

if (shouldTurnOff) {
    values.irrigationState = "DONE";
}

return {
    "ts": ctx.args.irrigationTask.ts,
    "values": values
}
